import {STATIONS,FIELDS,normalizeID,makeID,validID,strongPassword,bmi,validateData,mergeRecords,summarize,aggregateDays,pendingDays} from './core.js?v=1.0.3';
import {resolveContext} from './navigation.js?v=1.0.3';
import {Vault} from './vault.js?v=1.0.3';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cfg=window.WELLNESS_CONFIG,sb=window.supabase.createClient(cfg.url,cfg.key,{auth:{storageKey:'wellness-restaurant-auth-v1',persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}),vault=new Vault();
let state=null,page='home',eventID='',missionID='',station='registration',search='',busy=false,contextSyncPending=false,installPrompt=null,authMode='login',recovery=false,syncError='',impactFilter={scope:'approved',mission:'',from:'',to:'',location:''};
const labels={home:'Home',impact:'Mission analysis',guide:'Volunteer guide',stations:'Guest form',guests:'Guest records',events:'Missions & dates',appointments:'Appointments',programs:'Programs & recipes',reports:'Daily report',inventory:'Glasses inventory',team:'Volunteers',audit:'Edit history',settings:'Settings',sync:'Sync center',more:'More'};
const admin=()=>state?.user?.role==='admin',ev=()=>state?.events.find(e=>e.id===eventID),snap=()=>state?.snapshots[eventID]||{records:[],resources:[],audit:[],conflicts:[]};
const records=()=>mergeRecords(snap().records,state?.queue.filter(o=>o.event_id===eventID)||[]);
const assigned=()=>Object.keys(STATIONS);
const allowed=()=>admin()?Object.keys(labels):['home','guide','events','stations','guests','reports','inventory','sync','settings','more'];
const date=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Vientiane',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const button=(action,label,id='',kind='primary')=>`<button type="button" class="${kind}" data-action="${action}" data-id="${esc(id)}">${esc(label)}</button>`;
const field=(name,label,value='',type='text',attrs='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const area=(name,label,value='')=>`<label class="full">${esc(label)}<textarea name="${name}" rows="3" maxlength="4000">${esc(value)}</textarea></label>`;
const select=(name,label,options,value='')=>`<label>${esc(label)}<select name="${name}" aria-label="${esc(label)}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`;
const note=(t)=>`<div class="notice">${t}</div>`;
const empty=t=>`<p class="empty-copy">${esc(t)}</p>`;
const message=(text)=>{$('#authStatus').textContent=text;};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
async function api(action,data={},publicCall=false){
 const session=(await sb.auth.getSession()).data.session;
 const response=await fetch(cfg.url+'/functions/v1/wellness-api',{method:'POST',headers:{'Content-Type':'application/json',apikey:cfg.key,...(!publicCall&&session?{Authorization:'Bearer '+session.access_token}:{})},body:JSON.stringify({action,...data}),signal:AbortSignal.timeout(25000)});
 const json=await response.json();if(!response.ok)throw Object.assign(Error(json.error||'Connection failed.'),{status:response.status});return json;
}
function authView(mode='login'){
 authMode=mode;$('#loginGate').hidden=false;$('#app').hidden=true;
 if(mode==='unlockprevious'){$('#loginForm').innerHTML='<h1>Recover this phone’s saved entries</h1><p>No saved entries will be removed.</p>'+field('previous','Previous offline password','','password','required autocomplete="off"')+field('password','Current online password','','password','required autocomplete="current-password"')+'<p id="authStatus" role="status"></p><button type="submit" class="primary">Unlock and update this phone</button>'+button('login','Return to sign in','','text-button');$('#loginForm').onsubmit=authSubmit;return;}
 const signup=mode==='signup',password=mode==='password';
 $('#loginForm').innerHTML=`<img src="assets/logo.png" alt="Oon Jai" width="52" height="52"><h1>${signup?'Create a volunteer account':password?'Set a new password':'Oon Jai Wellness'}</h1><p>${signup?'Enter a shared mission code after signing up to open its day-and-location sessions.':password?'Choose a new password for your Wellness account.':'Sign in with your assigned email. Existing Restaurant accounts use their current password.'}</p>${signup?field('name','Full name','','text','required maxlength="120" autocomplete="name"'):''}${!password?field('email','Email address',localStorage.getItem('wellness-last-email')||'','email','required autocomplete="username"'):''}${mode!=='forgot'?field('password',password?'New password':'Password','','password',`required autocomplete="${signup||password?'new-password':'current-password'}"`):''}${signup||password?field('confirm','Confirm password','','password','required autocomplete="new-password"')+`<small>12–128 characters, uppercase and lowercase letters, a number and a symbol.</small>`:''}<div id="authStatus" role="status" aria-live="polite"></div><button class="primary" type="submit">${signup?'Create account':password?'Save password':mode==='forgot'?'Send recovery email':'Sign in'}</button>${mode==='login'?button('offline','Unlock saved phone offline','','secondary')+button('signup','Create an account','','text-button')+button('forgot','Forgot password?','','text-button')+button('resend','Resend verification','','text-button'):button('login','Return to sign in','','text-button')}`;
 $('#loginForm').onsubmit=authSubmit;
}
async function authSubmit(e){e.preventDefault();const form=e.target,b=form.querySelector('[type=submit]');b.disabled=true;const data=Object.fromEntries(new FormData(form));message('Please wait…');
 try{
  if(authMode==='unlockprevious'){const email=form.dataset.email;state=await vault.open(email,data.previous,false);const result=await sb.auth.signInWithPassword({email,password:data.password});if(result.error)throw result.error;if(state.user&&state.user.id!==result.data.user.id)throw Error('Account identity mismatch.');await vault.rekey(data.password);await refreshAccess();if(state.user.temporary_password){authView('password');return;}openWorkspace();await sync();return;}
  if(authMode==='signup'){if(data.password!==data.confirm)throw Error('Passwords do not match.');if(!strongPassword(data.password))throw Error('Use all the password requirements shown above.');const result=await api('signup',data,true);message(result.message);return;}
  if(authMode==='forgot'){const {error}=await sb.auth.resetPasswordForEmail(data.email,{redirectTo:cfg.recovery});if(error)throw error;message('Recovery requested. If the account exists, check your email. Use the newest email link to set your password here in Wellness.');return;}
  if(authMode==='password'){if(data.password!==data.confirm||!strongPassword(data.password))throw Error('Match both passwords and meet all requirements.');await api('password',{password:data.password});if(vault.key)await vault.rekey(data.password);vault.close();state=null;recovery=false;authView('login');message('Password updated. Sign in with your new password.');return;}
  const email=String(data.email).trim().toLowerCase();const {data:auth,error}=await sb.auth.signInWithPassword({email,password:data.password});if(error)throw error;
  try{state=await vault.open(email,data.password,true);}catch(error){if(error.code==='VAULT_PASSWORD'){authView('unlockprevious');$('#loginForm').dataset.email=email;message('Your online password works. Enter this phone’s previous password to recover its saved entries, then enter the current online password.');return;}throw error;}
  if(state.user&&state.user.id!==auth.user.id)throw Error('Offline account identity mismatch.');
  localStorage.setItem('wellness-last-email',email);
  await refreshAccess();if(state.user.temporary_password){authView('password');return;}
  openWorkspace();await sync();
 }catch(err){message(err.message||'Unable to sign in.');}finally{b.disabled=false;}
}
async function refreshAccess(){const b=await api('bootstrap');await vault.edit(s=>{s.user=b.member;s.events=b.events;s.assignments=b.assignments;s.members=b.members;s.missions=b.missions||[];s.memberships=b.memberships||[];s.grades=(b.grades||[]).sort((a,b)=>Number(a.grade)-Number(b.grade));s.alerts=b.alerts||[];s.totals=b.totals;s.dailyMetrics=b.dailyMetrics||[];s.missionCounts=b.missionCounts||{};s.preparedUntil=Date.now()+7*86400000;const ids=new Set(b.events.map(e=>e.id));for(const id of Object.keys(s.snapshots))if(!ids.has(id))delete s.snapshots[id];});state=vault.state;alignContext();}
function openWorkspace(){if(!state?.user)return;$('#loginGate').hidden=true;$('#app').hidden=false;page=allowed().includes(location.hash.slice(1))?location.hash.slice(1):'home';render();}
async function offline(){try{const d=Object.fromEntries(new FormData($('#loginForm')));state=await vault.open(String(d.email).trim(),d.password,false);if(!state.user)throw Error('Prepare the phone online first.');if(state.user.temporary_password)throw Error('Change your temporary password online first.');if(state.user.status==='disabled'||state.preparedUntil<Date.now())throw Error('Reconnect to refresh this phone’s access. Saved entries remain safe.');alignContext();openWorkspace();toast('Offline workspace unlocked. Only this phone’s saved data is available.');}catch(e){message(e.message);}}
function canWork(){if(state?.user?.status!=='active'||state.user.temporary_password)throw Error('Sign in and join the mission first.');if(!state.device)throw Error('Open Settings and prepare this phone while online first.');if(state.preparedUntil<Date.now())throw Error('Reconnect to renew this phone’s mission access. Your saved entries remain safe.');if(!ev()||ev().closed)throw Error('Choose an open event.');}
async function prepare(){await refreshAccess();if(!state.user.initials)throw Error('Your initials could not be reserved. Retry preparation online.');const d=await api('device',{id:state.deviceId,label:navigator.userAgent.includes('Mobile')?'Volunteer phone':'Computer / tablet'});await vault.edit(s=>{s.device=d;});state=vault.state;await navigator.storage?.persist?.();await sync();toast('Phone prepared. Sign in and choose this event before travelling.');}
async function sync(){if(busy||!state||!vault.key||!navigator.onLine)return;busy=true;syncError='';updateStatus();try{
 await navigator.locks.request('wellness-sync-'+vault.email,async()=>{
  if(!state||!vault.key)return;
  await refreshAccess();if(state.user.temporary_password){authView('password');return;}if(state.user.status!=='active')return;
  await vault.reload();state=vault.state;
  const touched=[...new Set([...(state.reportedDays||[]),...state.queue.map(o=>o.event_id),eventID].filter(id=>state.events.some(e=>e.id===id)))];
  for(const operation of [...state.queue].filter(o=>!['conflict','reviewed'].includes(o.status))){
   try{const result=await api('submit',{operation});await vault.edit(s=>{const q=s.queue.find(o=>o.id===operation.id);if(!q)return;if(result.status==='saved'){const snapshot=s.snapshots[q.event_id]||={records:[],resources:[],audit:[],conflicts:[]};snapshot.records=mergeRecords(snapshot.records,[{...q,author:s.user.id}]).map(r=>({...r,pending:false}));s.queue=s.queue.filter(o=>o.id!==q.id);}else{q.status=result.status;q.error=result.message;}});}
   catch(e){if(e.status===401||e.status===403)throw e;await vault.edit(s=>{const q=s.queue.find(o=>o.id===operation.id);if(q){q.status='error';q.error=e.message;}});if(!e.status)throw e;}
  }
  if(state.device)for(const report of pendingDays(vault.state.queue,touched).filter(d=>state.events.some(e=>e.id===d.event_id)))await api('device-status',{...report,device_id:state.device.id});
  const snapshotEvent=eventID;
  if(snapshotEvent){const snapshot=await api('snapshot',{event_id:snapshotEvent});await vault.edit(s=>{s.snapshots[snapshotEvent]=snapshot;const reviewed=new Set((snapshot.reviewed||[]).map(r=>r.id));s.queue=s.queue.filter(o=>!reviewed.has(o.id));});}
  await vault.edit(s=>{s.reportedDays=touched;s.lastSync=new Date().toISOString();});state=vault.state;
 });
 }catch(e){syncError=e.message||'Connection unavailable';toast(syncError);if(e.status===403){$('#dialog').close();authView('login');message(e.message);vault.close();state=null;}}
 finally{busy=false;updateStatus();if(state&&!$('#dialog').open&&!document.activeElement?.matches('input,textarea,select'))render();if(contextSyncPending){contextSyncPending=false;queueMicrotask(()=>sync());}}}
function updateStatus(){const t=$('#syncStatus');if(t)t.textContent=busy?'Syncing…':!navigator.onLine?'Offline':syncError?'Connection needs attention':state?.queue.length?`${state.queue.length} to sync / review`:'Connected';}
const dayPages=['home','stations','guests','reports','inventory','appointments','programs','audit','sync'];
const navGroups=[['Get started',['home','events']],['This day',['stations','guests','reports','inventory']],['Manage',['impact','appointments','programs','team','audit']],['Help & phone',['guide','sync','settings']]];
const pageHelp={home:'Start here, then follow your guest through the day.',events:'Choose your mission, then open its date and location.',stations:'Register a new guest or enter an existing guest ID.',guests:'Find a guest, recover an ID, or continue their form.',reports:'Review this day’s activity across every station.',inventory:'Check the glasses available for this day.',more:'Reports, team tools and help, all in one place.',settings:'Manage your account, phone and notifications.'};
const navPaths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',events:'M4 5h16v16H4ZM4 10h16M8 3v4m8-4v4',stations:'M9 4H5v17h14V4h-4M9 3h6v4H9ZM8 12h8m-8 4h5',guests:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M15 4a4 4 0 0 1 0 8m3 3a4 4 0 0 1 4 4v2M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',reports:'M4 20h16M7 16V9m5 7V4m5 12v-5',inventory:'M3 8h18v13H3ZM2 3h20v5H2Zm7 9h6',more:'M4 6h16M4 12h16M4 18h16',sync:'M3 11a9 9 0 0 1 15-6l3 3m0-5v5h-5M21 13A9 9 0 0 1 6 19l-3-3m0 5v-5h5',settings:'M12 3v3m0 12v3M3 12h3m12 0h3M6 6l2 2m8 8 2 2M6 18l2-2m8-8 2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',guide:'M4 4h7l1 2 1-2h7v16h-7l-1 1-1-1H4ZM12 6v15'};
const icon=p=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${navPaths[p]||navPaths.reports}"/></svg>`;
const navLink=(p,kind='nav-item',label=labels[p])=>`<a href="#${p}" class="${kind} ${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(p)}<span>${esc(label)}</span></a>`;
function alignContext(){const chosen=resolveContext(state,missionID||eventID?{missionID,eventID}:state.navigation,date());missionID=chosen.missionID;eventID=chosen.eventID;}
async function chooseContext(preferred){const chosen=resolveContext(state,preferred,date());await vault.edit(s=>{s.navigation=chosen;});state=vault.state;missionID=chosen.missionID;eventID=chosen.eventID;search='';render();if(busy)contextSyncPending=true;else await sync();}
function dayContext(){if(!state.missions?.length||!dayPages.includes(page))return '';const e=ev(),days=state.events.filter(d=>d.mission_id===missionID).sort((a,b)=>a.starts.localeCompare(b.starts)||a.location.localeCompare(b.location));return `<section class="day-context" aria-label="Selected mission and day"><div class="context-selects">${select('activeMission','1 · Mission',state.missions.map(m=>[m.id,m.name]),missionID)}${select('activeEvent','2 · Day and location',days.length?days.map(d=>[d.id,d.starts+' · '+d.location]):[['','No days scheduled']],eventID)}</div><div class="context-caption"><span>${e?esc(e.starts)+' · '+esc(e.location):'Choose a mission with a scheduled day.'}</span>${e?`<span class="badge ${e.sample?'gold':''}">${e.sample?'Fictional sample':e.approval==='approved'?'Approved · read only':e.closed?'Closed day':e.starts===date()?'Today':'Selected day'}</span>`:''}<a href="#events">View calendar →</a></div>${e?`<nav class="day-tabs" aria-label="Day workspace">${[['stations','Guest form'],['guests','Records'],['reports','Daily report'],['inventory','Glasses stock']].map(([p,l])=>navLink(p,'day-tab',l)).join('')}</nav>`:''}</section>`;}
function render(){
 if(!state)return;if(!allowed().includes(page))page='home';alignContext();
 $('#desktopNav').innerHTML=navGroups.map(([title,pages])=>{const visible=pages.filter(p=>allowed().includes(p));return visible.length?`<div class="nav-group"><p class="nav-label">${title}</p>${visible.map(p=>navLink(p)).join('')}</div>`:'';}).join('');
 const primary=['home','events','stations','guests'];$('#bottomNav').innerHTML=[...primary,'more'].map(p=>navLink(p,`bottom-link ${p==='more'&&!primary.includes(page)?'active':''}`,{home:'Home',events:'Missions',stations:'Guest form',guests:'Records',more:'More'}[p])).join('');
 $('#crumb').textContent=labels[page];$('.user-panel').innerHTML=`<span class="avatar">${esc(state.user.initials||'?')}</span><span>${esc(state.user.name)}<small>${admin()?'Administrator':'Volunteer'} · Lock / sign out</small></span>`;$('.desktop-avatar').textContent=state.user.initials||'?';
 const pending=state.user.status==='disabled';
 const top=`<div class="page-head"><div><div class="eyebrow">Oon Jai · Wellness</div><h1>${labels[page]}</h1><p class="subtext">${pageHelp[page]||'Your mission workspace.'}</p></div><div class="actions">${button('sync','Sync now','','secondary')}</div></div>${admin()&&state.alerts?.length?`<div class="admin-alert" role="alert"><strong>${state.alerts.length} conflicting submission${state.alerts.length===1?'':'s'} need review.</strong>${button('alerts','Review alerts','','secondary')}</div>`:''}${dayContext()}`;
 const content=dayPages.includes(page)&&page!=='home'&&page!=='sync'&&!ev()?()=>`<section class="panel"><h2>Choose a day to begin</h2><p class="subtext">Open a date and location from your mission calendar.</p><div class="actions spaced">${button('missions','Choose mission & day')}</div></section>`:({home:overview,impact:impactPage,guide:guidePage,stations:stationPage,guests:guestPage,events:eventPage,appointments:appointmentPage,programs:programPage,reports:reportPage,inventory:inventoryPage,team:teamPage,audit:auditPage,settings:settingsPage,sync:syncPage,more:morePage}[page]);
 $('#main').innerHTML=top+(pending?note('Your Wellness access is disabled. Contact an administrator. Saved entries remain on this phone.'):content());
 if(pending&&page==='settings')$('#main').innerHTML+=settingsPage();
 bindImpactFilters();bindGuide();
 const eventSelect=$('[name=activeEvent]');if(eventSelect)eventSelect.onchange=()=>chooseContext({missionID,eventID:eventSelect.value}).catch(e=>toast(e.message));
 const missionSelect=$('[name=activeMission]');if(missionSelect)missionSelect.onchange=()=>chooseContext({missionID:missionSelect.value}).catch(e=>toast(e.message));
 const searchInput=$('#guestSearch');if(searchInput)searchInput.oninput=()=>{search=searchInput.value;renderGuestList();};
 const idInput=$('#openGuestID');if(idInput)idInput.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();action('openform').catch(e=>toast(e.message));}};
 updateStatus();
}
function morePage(){const help={reports:'Activity and daily approval',inventory:'Grades, received and issued pairs',impact:'Approved results across missions',guide:'Practice and prepare for the trip',sync:'Saved entries and conflict review',settings:'Password, installation and notifications',team:'Volunteer accounts',audit:'Corrections for the selected day',appointments:'Schedule guest visits',programs:'Recipes and wellness activities'};return `<div class="more-grid">${navGroups.slice(1).filter(([,pages])=>pages.some(p=>allowed().includes(p))).map(([title,pages])=>`<section class="panel"><h2>${title}</h2><div class="menu-list">${pages.filter(p=>allowed().includes(p)).map(p=>`<a href="#${p}">${icon(p)}<span><strong>${labels[p]}</strong><small>${help[p]||pageHelp[p]||''}</small></span><span aria-hidden="true">→</span></a>`).join('')}</div></section>`).join('')}</div><div class="actions spaced">${button('signout','Lock / sign out','','secondary')}</div>`;}

function cards(m){return `<div class="stats">${[['People',m.guests],['Glasses pairs',m.glasses],['Dental cleanings',m.dental],['Health assessments',m.assessments]].map(([k,v])=>`<button class="stat" data-action="viewrecords"><div class="stat-top">${k}</div><div class="stat-value">${v}</div><div class="stat-foot">${ev()?.approval==='approved'?'Approved day':'Current day · preliminary'} · View records →</div></button>`).join('')}</div>`;}
function overview(){if(!ev())return welcomePage();const m=summarize(records());return `<section class="start-panel"><div><div class="eyebrow">Your daily workspace</div><h2>Ready for your next guest?</h2><p class="subtext">${esc(ev().location)} · ${esc(ev().starts)}. Every station connects through the guest’s ID.</p></div><div class="start-actions">${button('newregistration','Register a new guest')}${button('station','Enter a guest ID','','secondary')}<a href="#guests" class="text-button">Find a guest / recover an ID →</a></div></section>${!state.device?`<section class="prepare-banner"><div><strong>Get this phone ready before recording</strong><p class="subtext">Connect once to reserve IDs and prepare for offline work.</p></div>${button('prepare','Prepare this phone')}</section>`:''}<div class="section-heading"><h2>This day at a glance</h2><a href="#reports">Open daily report →</a></div>${cards(m)}<div class="grid-two"><section class="panel"><h2>Continue the day</h2><div class="menu-list"><a href="#reports">${icon('reports')}<span><strong>Daily report</strong><small>${m.registrations} registered · ${m.awaiting} awaiting registration</small></span><span>→</span></a><a href="#inventory">${icon('inventory')}<span><strong>Reading glasses stock</strong><small>Check available pairs by grade</small></span><span>→</span></a><a href="#events">${icon('events')}<span><strong>Missions & dates</strong><small>Choose another location or day</small></span><span>→</span></a></div></section><section class="panel"><h2>This phone</h2><p class="subtext">${state.device?'Ready for offline recording.':'Preparation needed before recording.'}</p><p class="subtext">${state.queue.length} submissions awaiting sync or review.</p><p class="subtext">${state.lastSync?'Last sync: '+esc(new Date(state.lastSync).toLocaleString()):'Not synced yet'}</p><div class="actions spaced">${button('syncpage','Open sync center','','secondary')}<a href="#guide" class="text-button">Volunteer guide →</a></div></section></div>${admin()&&state.totals?`<section class="panel"><div class="section-heading"><h2>Across all approved days</h2><a href="#impact">View mission analysis →</a></div><p class="subtext">${state.totals.real.guests} people · ${state.totals.real.glasses} glasses pairs · ${state.totals.real.dental} dental cleanings. Draft days and samples are excluded.</p></section>`:''}`;}

function stationPage(){if(!ev())return welcomePage();return `<div class="guest-entry-grid"><section class="panel guest-entry"><div class="step-marker">GUEST HAS AN ID</div><h2>Continue a guest’s form</h2><p class="subtext">Use the ID on their slip. Then choose the station you’re recording.</p><label class="spaced" for="openGuestID">Guest ID<input id="openGuestID" placeholder="SC-0002-000001-X" autocomplete="off" autocapitalize="characters" spellcheck="false"></label>${button('openform','Open guest form')}<a href="#guests" class="text-button spaced">Lost the slip? Find the guest’s ID →</a></section><section class="panel new-guest"><div class="step-marker">FIRST VISIT TODAY</div><h2>Register a new guest</h2><p class="subtext">Enter their personal details. The app creates the ID to use at every station.</p>${button('newregistration','New registration · generate ID','','secondary')}<p class="subtext">Already registered today? Use their existing ID to keep all records together.</p></section></div><details class="station-help"><summary>How the stations connect</summary><p class="subtext">Registration creates the ID. Every other station uses it, including offline. Entries join after the phones sync.</p><div class="station-tiles">${Object.values(STATIONS).map(s=>`<span>${esc(s)}</span>`).join('')}</div></details>`;}

function guestPage(){return `<section class="panel"><div class="panel-head"><div><h2>Combined daily guest records</h2><p>Joined by ID for this date and location. Unsynced records remain on their original phone.</p></div>${button('station','Open guest form','','secondary')}</div><label class="guest-search">Find a guest or recover a lost ID<input id="guestSearch" placeholder="Name, local name, phone, village or ID" value="${esc(search)}"></label><div id="guestList">${guestRows()}</div></section>`;}
function grouped(){const map=new Map();for(const r of records()){if(!map.has(r.guest_id))map.set(r.guest_id,{});map.get(r.guest_id)[r.station]=r;}return [...map.entries()];}
function guestRows(){const rows=grouped().filter(([id,r])=>[id,...Object.values(r).map(v=>JSON.stringify(v.data))].join(' ').toLowerCase().includes(search.toLowerCase()));return rows.map(([id,r])=>`<button class="guest-row" data-action="guest" data-id="${esc(id)}"><span class="avatar">${esc(r.registration?.data.name?.slice(0,2).toUpperCase()||'ID')}</span><span class="guest-info"><strong>${esc(r.registration?.data.name||(admin()?'Awaiting registration':'Guest ID record'))}</strong><small>${esc(r.registration?.data.local||'')} ${esc(r.registration?.data.village||'')}</small><span class="guest-code">${esc(id)}</span></span><span>${Object.keys(r).length} station${Object.keys(r).length===1?'':'s'}<br><small>${Object.values(r).some(v=>v.pending)?'Saved on phone':'Synced'}</small></span></button>`).join('')||empty('No matching records on this phone. Other phones must sync before their records appear for the team.');}
function renderGuestList(){if($('#guestList'))$('#guestList').innerHTML=guestRows();}
function show(title,body,submit,handler){$('#dialogBody').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2>${button('close','Close','','text-button')}</div><form id="modalForm">${body}<p id="formStatus" role="status" aria-live="polite"></p>${submit?`<div class="modal-footer"><button type="submit" class="primary">${esc(submit)}</button></div>`:''}</form>`;$('#dialog').showModal();$('#dialog').scrollTop=0;if(handler)$('#modalForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{await handler(Object.fromEntries(new FormData(e.target)),e.target);}catch(err){$('#formStatus').textContent=err.message;}finally{b.disabled=false;}};}
function stationFields(st,d={}){
 if(st==='registration')return field('name','Full name',d.name,'text','required maxlength="150"')+field('local','Name in Lao / Thai',d.local)+field('age','Age',d.age,'number','min="0" max="120" step="1"')+select('sex','Sex',['Not recorded','Female','Male','Other'],d.sex)+field('phone','Phone',d.phone,'tel')+select('country','Country',['Laos','Thailand','Other'],d.country||'Laos')+field('province','Province',d.province)+field('village','Village / district',d.village)+field('address','Address',d.address)+select('language','Language',['Lao','Thai','Hmong','English','Other'],d.language)+select('consent','Permission to record information',[['','Choose'],['yes','Guest / guardian agreed']],d.consent)+area('notes','Registration notes',d.notes);
 if(st==='measurements')return field('height','Height (cm)',d.height,'number','required min="30" max="250" step="0.1"')+field('weight','Weight (kg)',d.weight,'number','required min="1" max="400" step="0.1"')+field('waist','Waistline (cm)',d.waist,'number','min="20" max="250" step="0.1"')+`<div class="full bmi-box">BMI: <strong id="bmiValue">${bmi(d)||'—'}</strong><small>Calculated from entered measurements.</small></div>`+area('notes','Measurement notes',d.notes);
 if(st==='glasses')return select('status','Glasses outcome',['Provided','Assessed only','Referred'],d.status)+select('grade','Reading glasses grade',state.grades.map(g=>[g.grade,'+'+g.grade+' · '+remaining(g.grade)+' pairs remaining']),d.grade||'1.00')+field('quantity','Pairs provided',d.quantity||'1','number','min="0" max="20" step="1"')+area('notes','Glasses notes',d.notes);
 if(st==='dental')return select('status','Dental outcome',['Completed','Assessed only','Referred','Declined'],d.status)+area('notes','Dental notes',d.notes);
 if(st==='consultation')return area('reason','Reason for consultation',d.reason)+area('findings','Clinician findings',d.findings)+area('diagnoses','Confirmed diagnosis / source',d.diagnoses)+area('advice','Advice / follow-up',d.advice)+select('referral','Referral',['Not recorded','No','Yes'],d.referral)+field('clinician','Clinician / consultant',d.clinician)+area('notes','Consultation notes',d.notes);
 return field('systolic','Blood pressure: systolic (mmHg)',d.systolic,'number','min="40" max="300"')+field('diastolic','Blood pressure: diastolic (mmHg)',d.diastolic,'number','min="20" max="200"')+field('sugar','Blood sugar',d.sugar,'number','min="0.1" max="1000" step="0.1"')+select('sugarUnit','Blood sugar unit',['mg/dL','mmol/L'],d.sugarUnit)+select('sugarContext','Blood sugar context',['Not recorded','Fasting','Random','After meal'],d.sugarContext)+field('uric','Uric acid',d.uric,'number','min="0.1" max="1000" step="0.1"')+select('uricUnit','Uric acid unit',['mg/dL','µmol/L'],d.uricUnit)+area('symptoms','Symptoms reported by guest',d.symptoms)+area('diagnoses','Confirmed diagnosis / clinician source',d.diagnoses)+area('allergies','Allergies',d.allergies)+area('medications','Current medication',d.medications)+select('referral','Referral needed / arranged',['Not recorded','No','Yes'],d.referral)+area('notes','Assessment / referral details',d.notes);
}
async function stationForm(st=station,id='',record=null,alternate=false){canWork();if(!assigned().includes(st))throw Error('Unknown station.');if(record&&!admin())throw Error('Sub-users can create records only. Ask an administrator for a correction.');
 const currentEvent=eventID,currentSession={...ev()};
 if(!id){if(st!=='registration')throw Error('Enter the guest ID first.');await vault.edit(s=>{s.sequence++;id=makeID(s.device.prefix,s.device.code,s.sequence);});state=vault.state;}
 show((record?'Correct ':'')+STATIONS[st],`${note(esc(ev().starts)+' · '+esc(ev().location)+(ev().sample?' · Fictional sample event':''))}<div class="form-grid">${st==='registration'&&!id?note('A unique guest ID is assigned only after this phone safely saves the registration.'):field('guest_id','Guest ID',id,'text',`required autocomplete="off" autocapitalize="characters" ${id?'readonly':''}`)}${stationFields(st,record?.data)}</div>`,'Save on this phone',async(data)=>{
  const gid=normalizeID(data.guest_id||id);delete data.guest_id;const clean=validateData(st,data);if(!state.events.some(e=>e.id===currentEvent&&!e.closed))throw Error('This session was closed or your access changed. Your form has not been saved.');const mismatch=currentSession.starts!==date();if(mismatch&&!confirm('Date warning: this session is '+currentSession.starts+' at '+currentSession.location+', but today is '+date()+'. Save here anyway?'))return;if(gid&&!validID(gid))throw Error('Check the guest ID, including the final check character.');
  let saved;
  await vault.edit(s=>{if(s.deviceId!==s.device?.id)throw Error('Phone identity changed. Prepare it again.');let guestID=gid;if(!guestID){s.sequence++;guestID=makeID(s.device.prefix,s.device.code,s.sequence);}const existing=mergeRecords(s.snapshots[currentEvent]?.records||[],s.queue).find(r=>r.event_id===currentEvent&&r.guest_id===guestID&&r.station===st);if(existing&&!record&&!alternate)throw Error('This station already has a record for this guest. Ask an administrator to review it.');if(existing?.pending)throw Error('Sync the saved record before correcting it.');saved={id:crypto.randomUUID(),event_id:currentEvent,guest_id:guestID,station:st,data:clean,device_id:s.device.id,author:s.user.id,base_revision:record?.revision||null,status:'pending',created_at:new Date().toISOString(),captured_at:new Date().toISOString(),date_ack:mismatch};s.queue.push(saved);});
  state=vault.state;$('#dialog').close();render();show('Saved on this phone',`<p>Write this complete ID on the guest’s slip.</p><div class="id-slip">${esc(saved.guest_id)}</div><p>${esc(clean.name||STATIONS[st])}</p><p class="subtext">${esc(ev()?.name)} · ${navigator.onLine?'Syncing when a connection is available.':'Offline — safely queued on this phone.'}</p><div class="actions spaced">${button('copyid','Copy ID',saved.guest_id,'secondary')}${button('printid','Print ID slip',saved.guest_id,'secondary')}${button('conflictguest','Open complete form',saved.guest_id,'secondary')}</div>`,null);sync();
 });
 if(st==='measurements')$('#modalForm').oninput=()=>{const d=Object.fromEntries(new FormData($('#modalForm')));$('#bmiValue').textContent=bmi(d)||'—';};
}
function guestDetail(id){if(!validID(id))throw Error('Enter the complete guest ID, including the final check character.');const row=grouped().find(([g])=>g===id)?.[1]||{};show(row.registration?.data.name||'Guest form',`<div class="id-slip">${esc(id)}</div><p class="subtext">${esc(ev()?.starts)} · ${esc(ev()?.location)}</p>${button('copyid','Copy / recover ID',id,'secondary')}${!row.registration?note('Registration has not reached this phone yet. Other stations can still save with this ID.'):''}<div class="guest-station-grid">${Object.entries(STATIONS).map(([st,label])=>{const r=row[st];return `<section class="record-section guest-station"><h3>${label}</h3>${r?`<details><summary>${r.pending?'Saved on this phone':'Recorded'} · View details</summary><p class="subtext">${r.pending?'Saved on phone':'Synced'} · ${esc(state.members.find(m=>m.id===r.author)?.name||'Mission team')}</p><dl class="summary-grid">${Object.entries(r.data).filter(([,v])=>v).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}${st==='measurements'?`<dt>BMI</dt><dd>${bmi(r.data)}</dd>`:''}</dl>${!r.pending&&!ev()?.closed?(admin()?button('editrecord','Correct record',id+'|'+st,'secondary'):button('alternate','Submit a different record for review',id+'|'+st,'secondary')):''}</details>`:`<p class="subtext">Not yet recorded on this phone.</p>${!ev()?.closed?button('addsection','Record '+label,id+'|'+st):''}`}</section>`}).join('')}</div>`,null);}
function welcomePage(){return `<section class="hero"><div><div class="eyebrow">Welcome, ${esc(state.user.name)}</div><h2>Your next mission starts here.</h2><p>Join your team using the mission code from your leader. Each day and location has its own guest forms, stock and report.</p><div class="actions spaced">${button('joinmission','Enter mission code')}${button('guide','Practice before the trip','','secondary')}${admin()?button('missionform','Create mission','','secondary'):''}</div></div></section><div class="grid-two"><section class="panel"><h2>Before travelling</h2><p class="subtext">Join the mission, open its calendar and prepare this phone while online. Each phone receives a unique ID prefix automatically.</p></section><section class="panel"><h2>At the event</h2><p class="subtext">Use the guest ID at every station. Save offline, then sync before the day is reviewed. Your team’s daily progress is visible inside the mission.</p></section></div>`;}
function eventPage(){return `<div class="actions spaced">${button('joinmission','Join by mission code')}${admin()?button('missionform','Create mission','','secondary')+button('eventform','Add day / location','','secondary'):''}</div>${(state.missions||[]).map(m=>`<section class="panel spaced"><div class="panel-head"><div><div class="eyebrow">${m.sample?'Sample mission':'Mission trip'}</div><h2>${esc(m.name)}</h2><p class="subtext">${esc(m.notes)}</p>${admin()?`<p class="subtext">${state.missionCounts?.[m.id]||0} joined volunteer accounts</p>`:''}</div>${admin()?button('missionform','Edit / share code',m.id,'secondary'):''}</div>${admin()?`<p class="mission-code">Join code: <strong>${esc(m.code)}</strong></p>`:''}<div class="calendar-days">${state.events.filter(e=>e.mission_id===m.id).sort((a,b)=>a.starts.localeCompare(b.starts)||a.location.localeCompare(b.location)).map(e=>`<article class="calendar-day ${e.id===eventID?'selected':''} ${e.starts===date()?'today':''}"><div class="date-square">${esc(e.starts.slice(0,7))}<b>${esc(e.starts.slice(8))}</b></div><div><h3>${esc(e.location)}</h3><p class="subtext">${esc(e.name)} · ${e.starts===date()?'Today':esc(e.starts)}</p><span class="badge">${e.approval==='approved'?'Approved':'Daily workspace'}</span></div><div class="actions">${button('selectevent',e.id===eventID?'Continue this day':'Open day',e.id)}${admin()?button('eventform','Edit',e.id,'secondary'):''}</div></article>`).join('')||empty('No days scheduled yet.')}</div></section>`).join('')||welcomePage()}`;}
function missionForm(id){const m=state.missions.find(m=>m.id===id)||{};show(id?'Mission details':'Create a mission',`<div class="form-grid">${field('name','Mission name',m.name,'text','required placeholder="March 2027 mission trip"')}${field('code','Shared mission code',m.code,'text','required minlength="4" maxlength="50" placeholder="MT-03-2027" autocapitalize="characters"')}${select('active','Allow new members',[['true','Yes'],['false','No']],String(m.active!==false))}${area('notes','Mission notes',m.notes)}</div>`,'Save mission',async d=>{await api('mission',{mission:{...d,id:id||crypto.randomUUID(),revision:m.revision,code:d.code.trim().toUpperCase(),active:d.active==='true'}});await refreshAccess();$('#dialog').close();render();});}
function eventForm(id){const e=state.events.find(x=>x.id===id)||{};if(!state.missions.length)return missionForm();show(id?'Edit daily session':'Add day and location',`${note('Create a separate session for every date and location, including two days at the same venue.')}<div class="form-grid">${select('mission_id','Mission',state.missions.map(m=>[m.id,m.name]),e.mission_id||missionID)}${field('name','Session name',e.name,'text','required placeholder="Community outreach"')}${field('starts','Session date',e.starts||date(),'date','required')}${field('location','Location / venue / village',e.location,'text','required')}${select('country','Country',['Laos','Thailand','Other'],e.country)}${area('notes','Notes',e.notes)}</div>`,'Save day',async d=>{await api('event',{event:{...d,id:id||crypto.randomUUID(),revision:e.revision,ends:d.starts,closed:e.closed||false}});await refreshAccess();$('#dialog').close();render();});}
function serviceChart(m){const values=[['Registered',m.registrations],['Reading glasses',m.glassesPeople],['Dental cleaning',m.dental],['Blood tests / assessment',m.assessments],['Consultations',m.consultations],['Glasses + dental',m.both]];const max=Math.max(1,...values.map(v=>v[1]));return `<div class="service-chart" role="img" aria-label="Daily service counts: ${esc(values.map(v=>v.join(' ')).join(', '))}">${values.map(([label,n])=>`<div><span>${label}</span><i><b style="width:${n/max*100}%"></b></i><strong>${n}</strong></div>`).join('')}</div>`;}
function reportPage(){const rs=records(),m=summarize(rs);return cards(m)+`<section class="panel"><div class="panel-head"><h2>Daily assessment · ${ev()?.approval==='approved'?'approved':'preliminary'}</h2>${admin()?button('approve',ev()?.approval==='approved'?'Reopen day':'Review & approve day','','secondary'):''}${button('export','Export daily CSV','','secondary')}</div><p class="subtext">${esc(ev()?.name||'Choose an event')} · All stations for this date and location. Only approved real days enter main totals.</p><dl class="summary-grid"><dt>Registration records</dt><dd>${m.registrations}</dd><dt>Waiting for registration</dt><dd>${m.awaiting}</dd><dt>Height & weight / BMI</dt><dd>${m.measurements}</dd><dt>Health assessments</dt><dd>${m.assessments}</dd><dt>Consultations</dt><dd>${m.consultations}</dd><dt>Reading glasses recipients</dt><dd>${m.glassesPeople}</dd><dt>Both glasses and dental</dt><dd>${m.both}</dd><dt>Consultation without glasses / dental</dt><dd>${m.consultationOnly}</dd><dt>Referral recorded</dt><dd>${m.referrals}</dd><dt>Submissions needing review</dt><dd>${snap().conflicts?.length||0}</dd></dl>${serviceChart(m)}${note('Assessment summaries report what the team entered. The app does not generate diagnoses.')}<div class="table-wrap"><table><thead><tr><th>Guest / ID</th>${Object.values(STATIONS).map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${grouped().map(([id,r])=>`<tr><td><button class="text-button" data-action="guest" data-id="${esc(id)}">${esc(r.registration?.data.name||'Awaiting registration')}<br>${esc(id)}</button></td>${Object.keys(STATIONS).map(st=>`<td>${r[st]?(st==='measurements'?'BMI '+bmi(r[st].data):st==='glasses'?esc(r[st].data.status)+' · '+esc(r[st].data.quantity||0):st==='dental'?esc(r[st].data.status):'Recorded'):'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function teamPage(){return `<section class="panel"><div class="panel-head"><div><h2>${state.members.filter(m=>m.role==='volunteer').length} volunteer accounts</h2><p>People join using a mission code. No station assignments are needed.</p></div>${button('createuser','Add volunteer','','secondary')}</div>${state.members.map(m=>`<div class="guest-row"><span class="avatar">${esc(m.initials||'?')}</span><span class="guest-info"><strong>${esc(m.name)}</strong><small>${esc(m.email)}</small><small>${esc(m.id)}</small></span><span class="badge">${esc(m.role)} · ${esc(m.status)}</span>${button('memberform','Account status',m.id,'secondary')}</div>`).join('')}</section>`;}
function memberForm(id){const m=state.members.find(m=>m.id===id);show('Account status · '+m.name,`${note('Mission codes grant mission access. Initials and phone codes are reserved automatically.')}<p>${esc(m.email)} · ${esc(m.initials)}</p>${select('status','Status',['pending','active','disabled'],m.status)}`,'Save status',async d=>{await api('member',{id,status:d.status});await refreshAccess();$('#dialog').close();render();});}
function appointmentPage(){const list=snap().resources.filter(r=>r.kind==='appointment');return `<div class="actions spaced">${button('appointment','Schedule appointment')}</div><div class="event-grid">${list.map(r=>`<section class="panel"><span class="badge">${esc(r.data.status)}</span><h2>${esc(r.data.name)}</h2><p class="subtext">${esc(r.data.date)} ${esc(r.data.time)}<br>${esc(r.data.service)}<br>${esc(r.data.location)}</p>${button('appointment','Edit appointment',r.id,'secondary')}</section>`).join('')||empty('No appointments for this event.')}</div>`;}
function appointmentForm(id){const r=snap().resources.find(r=>r.id===id),d=r?.data||{};show('Appointment',`<div class="form-grid">${field('name','Guest name',d.name,'text','required')}${field('guest_id','Guest ID (if known)',d.guest_id)}${field('date','Date',d.date||date(),'date','required')}${field('time','Time',d.time||'09:00','time','required')}${select('service','Service',Object.values(STATIONS),d.service)}${select('status','Status',['Scheduled','Completed','Cancelled','Did not attend'],d.status)}${field('location','Location',d.location||ev()?.location)}${area('notes','Notes',d.notes)}</div>`,'Save appointment',async data=>{await api('resource',{resource:{id:id||crypto.randomUUID(),kind:'appointment',event_id:eventID,data,revision:r?.revision}});$('#dialog').close();await sync();});}
function programPage(){return `<div class="actions spaced">${button('recipe','Add recipe')}</div><div class="event-grid">${snap().resources.filter(r=>r.kind==='recipe').map(r=>`<section class="panel"><span class="badge">${esc(r.data.category)}</span><h2>${esc(r.data.name)}</h2><p class="subtext">${esc(r.data.description)}</p><p class="subtext">${esc(r.data.servings)} servings · ${esc(r.data.size)} ml each</p><div class="actions spaced">${button('recipeview','View / scale',r.id)}${button('recipe','Edit',r.id,'secondary')}</div></section>`).join('')||empty('No recipes saved yet.')}</div>`;}
function recipeForm(id){const r=snap().resources.find(r=>r.id===id),d=r?.data||{};show('Program recipe',`<div class="form-grid">${field('name','Recipe name',d.name,'text','required')}${select('category','Category',['Juicing','Wellness education','Detox / cleansing'],d.category)}${field('servings','Base servings',d.servings||'2','number','required min="1" max="10000"')}${field('size','Serving size (ml)',d.size||'250','number','required min="1"')}${area('description','Description',d.description)}${area('ingredients','Ingredients: one per line, ingredient | quantity | unit',d.ingredients)}${area('instructions','Preparation instructions',d.instructions)}${area('allergens','Allergens / ingredient cautions',d.allergens)}</div>`,'Save recipe',async data=>{await api('resource',{resource:{id:id||crypto.randomUUID(),kind:'recipe',event_id:null,data,revision:r?.revision}});$('#dialog').close();await sync();});}
function recipeView(id){const d=snap().resources.find(r=>r.id===id)?.data;if(!d)return;show(d.name,`${field('scale','Number of servings',d.servings,'number','min="1" max="10000"')}<div id="ingredients"></div><h3>Preparation</h3><p class="prewrap">${esc(d.instructions)}</p>${note(esc(d.allergens))}`,null);const paint=()=>{const scale=Number($('#modalForm [name=scale]').value)/Number(d.servings);$('#ingredients').innerHTML=`<ul>${String(d.ingredients).split('\n').map(line=>{const [name,q,unit]=line.split('|');return `<li>${esc(name)} · ${Number.isFinite(+q*scale)?(+q*scale).toFixed(1):esc(q)} ${esc(unit)}</li>`}).join('')}</ul>`;};$('#modalForm [name=scale]').oninput=paint;paint();}
function auditPage(){return `<section class="panel"><h2>Corrections and edits</h2><p class="subtext">New submissions are excluded. Latest 500 event edits.</p>${snap().audit.map(a=>`<details class="record-section"><summary>${esc(a.station)} · ${esc(a.guest_id||'Event')} · ${esc(new Date(a.created_at).toLocaleString())}</summary><p>${esc(state.members.find(m=>m.id===a.actor)?.name||'Team')}</p><div class="grid-two"><pre>${esc(JSON.stringify(a.before_data,null,2))}</pre><pre>${esc(JSON.stringify(a.after_data,null,2))}</pre></div></details>`).join('')||empty('No edits recorded for this event.')}</section>`;}
function settingsPage(){return `<div class="grid-two"><section class="panel"><h2>This phone</h2><p class="subtext">${esc(state.user.email)}<br>User ID: ${esc(state.user.id)}</p><p class="subtext">${state.device?'Phone code: '+esc(state.device.prefix)+'-'+String(state.device.code).padStart(4,'0'):'Not prepared yet'}</p><div class="actions spaced">${button('prepare','Prepare / refresh phone')}${button('password','Change password','','secondary')}</div>${note('Before travelling: sign in online, join the mission, select the day and location, prepare the phone, then test it in airplane mode. Offline access lasts 7 days after the last access refresh. Pending records stay saved until synced.')}</section><section class="panel"><h2>App & notifications</h2><div class="actions spaced"><a class="secondary" href="#guide">Volunteer guide</a><a class="secondary" href="#sync">Sync center</a></div><p class="subtext">Install this app from your browser menu for faster access.</p>${button('install','Install app','','secondary')}${admin()?button('pushenable','Enable administrator notifications','','secondary')+button('pushtest','Send a test notification','','secondary')+button('pushdisable','Disable notifications here','','text-button'):''}${button('checkupdates','Check for updates','','secondary')}<p id="updateStatus" class="subtext">Wellness 1.0.3</p></section></div>`;}
function syncPage(){return `<section class="panel"><div class="panel-head"><h2>Saved on this phone</h2>${button('sync','Retry sync','','secondary')}</div>${note('Keep this phone’s browser data until every submission is synced. Closing or restarting the app keeps saved entries. Internet access is needed only for preparation, sign-up, password recovery and synchronization.')} ${state.queue.map(o=>`<article class="record-section"><h3>${esc(o.guest_id)} · ${STATIONS[o.station]}</h3><span class="badge">${esc(o.status)}</span><p class="subtext">${esc(o.error||'Waiting for connection')}</p><p class="subtext">${esc(state.events.find(e=>e.id===o.event_id)?.name||'Event access changed')}</p></article>`).join('')||empty('All submissions from this phone are synced.')}</section>${admin()?`<section class="panel spaced"><h2>Event conflicts · administrator review</h2>${snap().conflicts.map(c=>`<article class="record-section"><h3>${esc(c.operation.guest_id)} · ${esc(STATIONS[c.operation.station])}</h3><p class="subtext">${esc(state.members.find(m=>m.id===c.user_id)?.name||'Volunteer')}</p><pre>${esc(JSON.stringify(c.operation.data,null,2))}</pre><div class="actions">${button('reviewconflict','Compare / correct',c.id)}${button('resolveconflict','Keep current record',c.id,'secondary')}</div></article>`).join('')||empty('No event conflicts.')}</section>`:''}`;}
function exportCSV(){const rows=[['Event','Event ID','Guest ID','Station','Field','Value','Author','Saved at']];for(const r of records())for(const [k,v]of Object.entries(r.data))rows.push([ev()?.name,eventID,r.guest_id,STATIONS[r.station],k,v,state.members.find(m=>m.id===r.author)?.name||r.author,r.updated_at||r.created_at]);const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Wellness-event-records.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function remaining(grade){const opening=Number(snap().stock?.find(s=>s.grade===grade)?.received||0);const issued=records().filter(r=>r.station==='glasses'&&r.data.grade===grade&&r.data.status==='Provided').reduce((n,r)=>n+Number(r.data.quantity||0),0);return opening-issued;}
function inventoryPage(){if(!ev())return welcomePage();return `<section class="panel"><div class="panel-head"><div><h2>Reading glasses · stock by grade</h2><p>${esc(ev().starts)} · ${esc(ev().location)}</p></div><div class="actions">${admin()?button('stockform','Receive / adjust stock','','secondary')+button('gradeform','Add grade','','secondary'):''}</div></div>${note('Issued pairs come from the accepted glasses record for each guest. Duplicate/conflicting submissions do not reduce stock twice. Offline balances reflect this phone’s last sync; reconcile after every phone syncs.')}<div class="table-wrap"><table><thead><tr><th>Grade</th><th>Received / adjusted</th><th>Issued</th><th>Remaining</th></tr></thead><tbody>${state.grades.map(g=>{const received=Number(snap().stock?.find(s=>s.grade===g.grade)?.received||0),left=remaining(g.grade);return `<tr><td>+${esc(g.grade)}</td><td>${received}</td><td>${received-left}</td><td class="${left<0?'stock-negative':''}">${left}${left<0?' · reconcile':''}</td></tr>`}).join('')}</tbody></table></div></section>`;}
function stockForm(){if(!ev())throw Error('Choose a day and location.');const opid=crypto.randomUUID();show('Receive or adjust glasses',`<div class="form-grid">${select('grade','Grade',state.grades.map(g=>[g.grade,'+'+g.grade]))}${field('quantity','Quantity change (pairs)','','number','required step="1"')}${area('note','Reason / delivery reference')}</div><p class="subtext">Use a positive number to receive stock or a negative number for a correction. Dispensing is counted automatically from guest records.</p>`,'Save stock change',async d=>{await api('stock',{...d,id:opid,event_id:eventID});$('#dialog').close();await sync();});}
function approveDay(){if(state.queue.some(o=>o.event_id===eventID&&!['conflict','reviewed'].includes(o.status)))throw Error('Sync this phone’s pending entries before reviewing the day.');if(!ev())throw Error('Choose a day first.');const approved=ev().approval==='approved';show(approved?'Reopen approved day':'Daily review and approval',`${note(approved?'Reopening removes this day from the main approved totals until you approve it again.':'Check the daily report, resolve conflicts, recover missing registration details and reconcile stock. Every field phone must sync before approval.')}<dl class="summary-grid"><dt>Date</dt><dd>${esc(ev().starts)}</dd><dt>Location</dt><dd>${esc(ev().location)}</dd><dt>Reported phones</dt><dd>${snap().devices?.length||0}</dd><dt>Pending reported by phones</dt><dd>${(snap().devices||[]).reduce((n,d)=>n+d.pending,0)}</dd><dt>Unresolved conflicts</dt><dd>${snap().conflicts?.length||0}</dd></dl>${!approved?`<label class="checkline"><input type="checkbox" name="phones_confirmed" required>I checked with the team: all phones have synced and this day is ready.</label><p class="subtext">A phone that has not connected cannot report its unsynced entries. This confirmation is required before adding results to the main totals.</p>`:''}`,approved?'Reopen day':'Approve day',async d=>{await api('approve',{event_id:eventID,approved:!approved,phones_confirmed:d.phones_confirmed==='on'});$('#dialog').close();await sync();});}
function alertsView(){show('Administrator alerts',`${note('All administrator accounts see unresolved conflicts on refresh. No earlier record is overwritten. Open the affected day to compare both submissions.')} ${(state.alerts||[]).map(a=>`<article class="record-section"><h3>${esc(a.operation.guest_id)} · ${esc(STATIONS[a.operation.station])}</h3><p>${esc(state.events.find(e=>e.id===a.operation.event_id)?.name||'Session')}</p>${button('alertday','Review this day',a.operation.event_id,'secondary')}</article>`).join('')||empty('No unresolved conflicts.')}`,null);}
async function action(name,id){
 if(name==='close'){$('#dialog').close();return;}
 if(name==='login'||name==='signup'||name==='forgot'){authView(name);return;}
 if(name==='offline'){await offline();return;}
 if(name==='resend'){const email=$('#loginForm [name=email]').value;if(!email)throw Error('Enter your email first.');const {error}=await sb.auth.resend({type:'signup',email,options:{emailRedirectTo:location.origin+location.pathname}});if(error)throw error;message('Verification email requested. Confirm your email, then return here.');return;}
 if(name==='signout'){if(state?.queue.length&&!confirm('Your unsynced entries will stay encrypted on this phone. Lock and sign out?'))return;await navigator.locks.request('wellness-sync-'+vault.email,async()=>{await sb.auth.signOut({scope:'local'});vault.close();state=null;missionID='';eventID='';search='';$('#dialog').close();authView();});return;}
 if(!state)throw Error('Sign in first.');
 if(name==='sync')return sync();if(name==='prepare')return prepare();
 if(name==='station'||name==='viewrecords'||name==='report'||name==='syncpage'){location.hash=({station:'stations',viewrecords:'guests',report:'reports',syncpage:'sync'})[name];return;}
 if(name==='stationform'||name==='newregistration')return stationForm('registration');
 if(name==='openform'){const id=normalizeID($('#openGuestID').value);if(!validID(id))throw Error('Enter the complete guest ID before proceeding.');return guestDetail(id);}
 if(name==='addsection'||name==='alternate'){const [gid,st]=id.split('|');$('#dialog').close();return stationForm(st,gid,null,name==='alternate');}
 if(name==='joinmission')return show('Join a mission',`${field('code','Mission code','','text','required placeholder="MT-03-2027" autocapitalize="characters"')}<p class="subtext">Your leader provides the code. It opens all scheduled dates, locations and stations within that mission.</p>`,'Join mission',async d=>{const r=await api('join',{code:d.code.trim().toUpperCase()});await refreshAccess();await chooseContext({missionID:r.mission_id});$('#dialog').close();location.hash='events';render();if(eventID)await prepare();});
 if(name==='missionform')return missionForm(id);
 if(name==='missions'){location.hash='events';return;}if(name==='guide'){location.hash='guide';return;}if(name==='impact'){location.hash='impact';return;}if(name==='impactexport')return exportImpact();
 if(name==='stockform')return stockForm();
 if(name==='gradeform')return show('Add glasses grade',field('grade','Grade','','number','required min="0.01" max="30" step="0.01"'),'Add grade',async d=>{await api('grade',d);await refreshAccess();$('#dialog').close();render();});
 if(name==='pushenable'||name==='pushdisable'||name==='pushtest')return notifications(name);
 if(name==='approve')return approveDay();
 if(name==='alerts')return alertsView();
 if(name==='guest')return guestDetail(id);
 if(name==='printid'){const slip=$('.id-slip');if(slip){slip.classList.add('print-slip');window.print();slip.classList.remove('print-slip');}return;}if(name==='copyid'){await navigator.clipboard.writeText(id);toast('Guest ID copied.');return;}
 if(name==='editrecord'){const [gid,st]=id.split('|'),r=records().find(r=>r.guest_id===gid&&r.station===st);$('#dialog').close();return stationForm(st,gid,r);}
 if(name==='selectevent'){const selected=state.events.find(e=>e.id===id);if(!selected)throw Error('This day is no longer available.');await chooseContext({eventID:id,missionID:selected.mission_id});location.hash='stations';return;}
 if(name==='eventform')return eventForm(id);
 if(name==='memberform')return memberForm(id);
 if(name==='createuser')return show('Add volunteer',`<p>The new volunteer verifies their email and uses it as a temporary password. They must choose a strong password before accessing records.</p><div class="form-grid">${field('name','Full name','','text','required')}${field('email','Email','','email','required')}</div>`,'Create volunteer',async d=>{const r=await api('create-user',d);await refreshAccess();$('#dialog').close();render();toast(r.message);});
 if(name==='appointment')return appointmentForm(id);
 if(name==='recipe')return recipeForm(id);
 if(name==='recipeview')return recipeView(id);
 if(name==='export')return exportCSV();
 if(name==='password'){authView('password');return;}
 if(name==='alertday'){$('#dialog').close();const selected=state.events.find(e=>e.id===id);if(!selected)throw Error('This day is no longer available.');await chooseContext({eventID:id,missionID:selected.mission_id});location.hash='sync';return;}
 if(name==='resolveconflict'){await api('resolve',{id});await sync();return;}
 if(name==='reviewconflict'){const c=snap().conflicts.find(c=>c.id===id),o=c.operation,r=records().find(r=>r.guest_id===o.guest_id&&r.station===o.station);if(!r)throw Error('Sync the event before reviewing.');show('Compare station submissions',`<div class="grid-two"><section><h3>Current record</h3><pre>${esc(JSON.stringify(r.data,null,2))}</pre></section><section><h3>Incoming submission</h3><pre>${esc(JSON.stringify(o.data,null,2))}</pre></section></div><p>After reviewing, open the guest record to make a correction, or keep the current version.</p>${button('conflictguest','Open current record',o.guest_id,'secondary')}`,null);return;}
 if(name==='conflictguest'){$('#dialog').close();return guestDetail(id);}
 if(name==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else toast('Open your browser menu and choose Install app or Add to Home Screen.');return;}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){action(el.dataset.action,el.dataset.id||'').catch(e=>{if(!$('#loginGate').hidden)message(e.message);else toast(e.message);});}});
window.addEventListener('hashchange',()=>{if(!state)return;page=location.hash.slice(1)||'home';render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
window.addEventListener('online',()=>sync());window.addEventListener('offline',updateStatus);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state)sync();});
setInterval(()=>{if(document.visibilityState==='visible'&&state&&!$('#dialog').open)sync();},30000);
// Every reload requires the password to decrypt this phone. An Auth session alone cannot open the vault.
sb.auth.onAuthStateChange(event=>{if(event==='PASSWORD_RECOVERY'){recovery=true;setTimeout(()=>authView('password'),0);}});
authView();
if(new URLSearchParams(location.hash.slice(1)).has('error_description'))message(new URLSearchParams(location.hash.slice(1)).get('error_description'));

function selectedImpact(){const source=(state.dailyMetrics||[]).filter(d=>impactFilter.scope==='samples'?d.sample:d.approval==='approved'&&!d.sample);return aggregateDays(source,impactFilter);}
function impactPage(){const {days,total}=selectedImpact(),locations=[...new Set((state.dailyMetrics||[]).map(d=>d.location))].sort();return `<section class="panel"><h2>Combined mission analysis</h2><p class="subtext">Approved results by mission, date and location. Visits count each day separately, including returning guests.</p><div class="form-grid spaced" id="impactFilters">${select('scope','Report data',[['approved','Approved real days'],['samples','Fictional training preview']],impactFilter.scope)}${select('mission','Mission filter',[['','All missions'],...state.missions.map(m=>[m.id,m.name])],impactFilter.mission)}${field('from','From date',impactFilter.from,'date')}${field('to','Through date',impactFilter.to,'date')}${select('location','Location filter',[['','All locations'],...locations],impactFilter.location)}</div>${impactFilter.scope==='samples'?note('Training preview only. These fictional results are excluded from official totals.'):''}${impactFilter.from&&impactFilter.to&&impactFilter.from>impactFilter.to?note('Choose an end date on or after the start date.'):''}<div class="stats">${[['Days / locations',days.length],['Guest visits',total.visits],['Registered visits',total.registrations],['Glasses pairs',total.glasses]].map(([label,n])=>`<div class="stat"><div class="stat-top">${label}</div><div class="stat-value">${n}</div></div>`).join('')}</div><div class="actions">${button('impactexport','Export analysis CSV','','secondary')}</div></section><div class="grid-two spaced"><section class="panel"><h2>Services delivered</h2>${serviceChart(total)}<p class="subtext">${total.both} visits received both glasses and dental care. ${total.consultationOnly} consultations did not receive glasses or dental cleaning.</p></section><section class="panel"><h2>Registrations by day</h2>${impactBars(days.reduce((map,d)=>(map[d.starts]=(map[d.starts]||0)+d.metrics.registrations,map),{}))}</section></div><section class="panel"><h2>Results by location</h2>${impactBars(days.reduce((map,d)=>(map[d.location]=(map[d.location]||0)+d.metrics.visits,map),{}),'guest visits')}<div class="table-wrap"><table><thead><tr><th>Date</th><th>Location</th><th>Registered</th><th>Glasses recipients</th><th>Dental</th><th>Consultations</th><th>Assessments</th></tr></thead><tbody>${days.sort((a,b)=>a.starts.localeCompare(b.starts)||a.location.localeCompare(b.location)).map(d=>`<tr><td>${esc(d.starts)}</td><td><button class="text-button" data-action="selectevent" data-id="${esc(d.id)}">${esc(d.location)}</button></td><td>${d.metrics.registrations}</td><td>${d.metrics.glassesPeople}</td><td>${d.metrics.dental}</td><td>${d.metrics.consultations}</td><td>${d.metrics.assessments}</td></tr>`).join('')}</tbody></table></div>${!days.length?empty('No matching days. Approve a completed day or choose the fictional training preview.'):''}</section>`;}
function impactBars(values,unit='registrations'){const items=Object.entries(values).sort(([a],[b])=>a.localeCompare(b)),max=Math.max(1,...items.map(([,n])=>n));return `<div class="service-chart" role="img" aria-label="${esc(items.map(([label,n])=>label+': '+n+' '+unit).join('; ')||'No data')}">${items.map(([label,n])=>`<div><span>${esc(label)}</span><i><b style="width:${100*n/max}%"></b></i><strong>${n}</strong></div>`).join('')}</div>`;}
function bindImpactFilters(){const f=$('#impactFilters');if(!f)return;f.querySelectorAll('input,select').forEach(input=>input.onchange=()=>{impactFilter[input.name]=input.value;render();});}
function exportImpact(){const {days}=selectedImpact(),rows=[['Date','Location','Mission','Status','Guest visits','Registered','Glasses recipients','Glasses pairs','Dental cleanings','Consultations','Assessments','Glasses and dental','Consultation only','Referrals'],...days.map(d=>[d.starts,d.location,state.missions.find(m=>m.id===d.mission_id)?.name,d.sample?'Fictional sample':d.approval,d.metrics.visits,d.metrics.registrations,d.metrics.glassesPeople,d.metrics.glasses,d.metrics.dental,d.metrics.consultations,d.metrics.assessments,d.metrics.both,d.metrics.consultationOnly,d.metrics.referrals])];downloadCSV(rows,'Wellness-mission-analysis.csv');}
function downloadCSV(rows,name){const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function guidePage(){return `<section class="hero"><div><div class="eyebrow">Volunteer preparation</div><h2>Ready before the first guest arrives.</h2><p>Practice here while waiting for your mission code. Practice values stay on this screen and never create guest records.</p><div class="actions">${button('joinmission','Enter mission code')}${button('prepare','Prepare / refresh phone','','secondary')}</div></div></section><div class="grid-two"><section class="panel"><h2>Before leaving</h2>${[['joined','I have joined the correct mission.'],['session','I checked the date and location.'],['phone','I prepared this phone online.'],['airplane','I tested opening the app in airplane mode.'],['power','I have charged the phone and arranged a power bank.']].map(([id,label])=>`<label class="checkline"><input type="checkbox" data-ready="${id}" ${state.readiness?.[id]?'checked':''}>${label}</label>`).join('')}<p class="subtext">Your checklist is saved on this phone. Each phone must prepare separately.</p></section><section class="panel"><h2>Practice a guest ID</h2><p class="subtext">Type this example, including its final check character:</p><div class="id-slip">${makeID('DEMO',1,1)}</div>${field('practiceID','Practice ID','','text','autocomplete="off" autocapitalize="characters"')}<p id="practiceIDResult" role="status" class="subtext">No guest will be created.</p></section><section class="panel"><h2>Practice height, weight and BMI</h2><div class="form-grid">${field('practiceHeight','Practice height (cm)','170','number','min="30" max="250" step="0.1"')}${field('practiceWeight','Practice weight (kg)','68','number','min="1" max="400" step="0.1"')}</div><p class="bmi-box">Calculated BMI: <strong id="practiceBMI">23.5</strong></p><p class="subtext">This demonstrates the calculation only. Enter real measurements in the guest’s event form.</p></section><section class="panel"><h2>Station handover</h2><ol class="guide-steps"><li>Check the event date and location.</li><li>Registration creates the ID and gives it to the guest.</li><li>Every station enters the complete ID, then records its section.</li><li>If registration is not visible, continue using the ID.</li><li>Save on the phone. When connected, open the app and sync.</li><li>Tell the administrator when your phone has no pending uploads.</li></ol><p class="subtext">A lost slip can be recovered on the registration phone, or on another phone after registration syncs. Conflicting records go to administrator review.</p></section></div>`;}
function bindGuide(){document.querySelectorAll('[data-ready]').forEach(input=>input.onchange=async()=>{try{await vault.edit(s=>{(s.readiness||={})[input.dataset.ready]=input.checked;});state=vault.state;}catch(e){toast(e.message);}});const id=$('[name=practiceID]');if(id)id.oninput=()=>{$('#practiceIDResult').textContent=validID(normalizeID(id.value))?'Complete ID with a valid check character. This practice did not save a guest.':'Check every part of the ID, including the last character.';};for(const name of ['practiceHeight','practiceWeight']){const input=$('[name='+name+']');if(input)input.oninput=()=>{const data={height:$('[name=practiceHeight]').value,weight:$('[name=practiceWeight]').value};try{validateData('measurements',data);$('#practiceBMI').textContent=bmi(data);}catch{$('#practiceBMI').textContent='Check measurements';}};}}

async function notifications(action){
 if(!admin())throw Error('Administrator access required.');if(!navigator.onLine)throw Error('Connect to set up notifications.');
 if(!('serviceWorker' in navigator)||!('PushManager' in window)||!('Notification' in window))throw Error('Notifications are unavailable in this browser. On iPhone, add Wellness to the Home Screen, then open the installed app.');
 const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();
 if(action==='pushdisable'){if(sub){await api('push-unsubscribe',{endpoint:sub.endpoint});await sub.unsubscribe();}toast('Notifications disabled on this phone.');return;}
 if(action==='pushtest'){if(!sub)throw Error('Enable notifications on this phone first.');await api('push-test',{endpoint:sub.endpoint});toast('Test notification sent.');return;}
 if(Notification.permission==='denied')throw Error('Notifications are blocked. Enable them in your browser or phone settings, then try again.');
 const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notifications were not enabled. In-app alerts remain available.');
 const {publicKey}=await api('push-key');if(!sub){const text=publicKey.replace(/-/g,'+').replace(/_/g,'/'),key=Uint8Array.from(atob(text+'='.repeat((4-text.length%4)%4)),c=>c.charCodeAt(0));sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});}
 await api('push-subscribe',{subscription:sub.toJSON()});toast('Administrator notifications enabled on this phone.');
}
